import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.CRFziyHp.js";const c=JSON.parse('{"title":"地图与定位","description":"地图与定位：灵萌 功能开启官方文档，面向站点管理员与运营人员，含配置步骤与注意事项。","frontmatter":{},"headers":[],"relativePath":"features/map.md","filePath":"features/map.md","lastUpdated":1785018026000}'),l={name:"features/map.md"};function i(n,t,s,d,h,u){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="地图与定位" tabindex="-1">地图与定位 <a class="header-anchor" href="#地图与定位" aria-label="Permalink to &quot;地图与定位&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>接入高德地图，为定位、距离筛选、外卖与跑腿派单等本地生活功能提供地理能力。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>已在 <a href="https://console.amap.com/" target="_blank" rel="noreferrer">高德开放平台</a> 创建应用，并开通 <strong>Web 端（JS API）</strong> 类型 Key。</li><li>2021 年后创建的应用须同时配置 <strong>安全密钥（securityJsCode）</strong>。</li><li>若使用外卖 / 跑腿模块，对应功能已在授权中开通。</li></ul><h2 id="管理后台配置步骤" tabindex="-1">管理后台配置步骤 <a class="header-anchor" href="#管理后台配置步骤" aria-label="Permalink to &quot;管理后台配置步骤&quot;">​</a></h2><p>路径：<strong>系统设置 → 系统配置 → 高德地图</strong> Tab</p><table tabindex="0"><thead><tr><th>配置项</th><th>说明</th></tr></thead><tbody><tr><td>Web 端 Key</td><td>高德控制台 → 应用 → Key</td></tr><tr><td>安全密钥</td><td>与 Key 同应用下的安全密钥</td></tr></tbody></table><p>保存后无需重启；客户端下次加载地图组件时生效。</p><h3 id="与站点区域的关系" tabindex="-1">与站点区域的关系 <a class="header-anchor" href="#与站点区域的关系" aria-label="Permalink to &quot;与站点区域的关系&quot;">​</a></h3><p>路径：<strong>系统设置 → 系统配置 → 区域配置</strong> Tab（或 <strong>区域管理 → 区域列表</strong>）</p><p>可设置 <strong>距离限制</strong>（米）：用户可见笔记、商家等内容的最大地理半径。与高德 Key 配合使用。</p><h2 id="区域配置" tabindex="-1">区域配置 <a class="header-anchor" href="#区域配置" aria-label="Permalink to &quot;区域配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>菜单</th><th>作用</th></tr></thead><tbody><tr><td><strong>系统配置 → 区域配置</strong></td><td>全站区域模式、默认距离限制</td></tr><tr><td><strong>区域管理 → 区域列表</strong></td><td>各区域中心点、半径等（如有）</td></tr><tr><td><strong>商户管理 → 外卖 → 区域外卖配置</strong></td><td>外卖配送范围、起送价等</td></tr><tr><td><strong>商户管理 → 跑腿 → 跑腿区域配置</strong></td><td>跑腿服务范围与计价</td></tr></tbody></table><p>地图 Key 为全站共用；业务半径按区域单独配置。</p><h2 id="验证是否生效" tabindex="-1">验证是否生效 <a class="header-anchor" href="#验证是否生效" aria-label="Permalink to &quot;验证是否生效&quot;">​</a></h2><ol><li>客户端打开带地图的页面（如地址选择、附近内容），地图正常加载、可定位。</li><li>外卖：商家入驻后，用户端能看到符合配送范围的店铺；下单时距离计算合理。</li><li>跑腿：创建跑腿单时起点终点解析正常，费用与距离匹配。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>地图空白或报 INVALID_USER_KEY</strong></p><ul><li>Key 类型须为 Web 端，不是 Android / iOS SDK Key。</li><li>安全密钥必须与 Key 配对填写；漏填会导致 JS API 报错。</li></ul><p><strong>定位偏差大</strong></p><ul><li>浏览器 / 小程序需用户授权位置；HTTPS 环境下定位更稳定。</li><li>检查 <strong>区域配置</strong> 中的距离限制是否过小，导致内容被过滤。</li></ul><p><strong>外卖派单找不到骑手</strong></p><ul><li>地图 Key 正确仅解决坐标问题；派单还依赖 <strong>区域外卖配置</strong> 中的策略与骑手在线状态，见 <a href="/features/takeaway">外卖</a>、<a href="/features/rider">骑手</a>。</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/features/takeaway">外卖</a></li><li><a href="/features/errand">跑腿</a></li><li><a href="/config/system-settings">系统配置总览</a></li></ul>',26)])])}const b=a(l,[["render",i]]);export{c as __pageData,b as default};
